def solve(a, n):
    """Write a python function to check whether the count of inversion of two types are same or not.

    The two types are global and local inversions:

    * a *local* inversion is a pair ``(i, i + 1)`` with ``a[i] > a[i + 1]``;
    * a *global* inversion is a pair ``(i, j)`` with ``i < j`` and
      ``a[i] > a[j]``.

    Every local inversion is also a global inversion, and every global
    inversion is either local (``j == i + 1``) or non-local
    (``j > i + 1``).  Hence the two counts are equal if and only if there
    is no non-local inversion, i.e. no ``a[i] > a[j]`` with ``j >= i + 2``.
    Scanning ``j`` from left to right while keeping the maximum of
    ``a[0:j - 1]`` detects such a pair in linear time.

    ``n`` is the number of leading elements of ``a`` to consider.
    """
    if a is None:
        return True
    try:
        length = int(n)
    except (TypeError, ValueError):
        length = len(a)
    if length < 0:
        length = 0
    if length > len(a):
        length = len(a)
    if length <= 2:
        return True

    prefix_max = a[0]
    for j in range(2, length):
        # prefix_max is max(a[0], ..., a[j - 2]) at this point.
        if prefix_max > a[j]:
            return False
        if a[j - 1] > prefix_max:
            prefix_max = a[j - 1]
    return True
