import solution


def test_module_imports():
    assert solution is not None


def _counts_are_equal(a):
    """Brute-force comparison of global and local inversion counts."""
    global_count = sum(
        1
        for i in range(len(a))
        for j in range(i + 1, len(a))
        if a[i] > a[j]
    )
    local_count = sum(1 for i in range(len(a) - 1) if a[i] > a[i + 1])
    return global_count == local_count


def test_example():
    assert solution.solve([1, 0, 2], 3) == True


def test_non_local_inversion_makes_counts_differ():
    # Global inversions: (1, 0) and (2, 0); local inversions: only (2, 0).
    assert solution.solve([1, 2, 0], 3) == False
    # Global inversions: (2, 0), (2, 1); local inversions: only (2, 0).
    assert solution.solve([2, 0, 1], 3) == False
    assert solution.solve([2, 1, 0], 3) == False
    assert solution.solve([3, 1, 2], 3) == False


def test_equal_counts():
    assert solution.solve([0, 1, 2, 3], 4) == True
    assert solution.solve([1, 0, 2, 3], 4) == True
    assert solution.solve([0, 2, 1, 3], 4) == True
    assert solution.solve([2, 1], 2) == True
    assert solution.solve([1, 1, 1], 3) == True


def test_empty_and_single_element():
    assert solution.solve([], 0) == True
    assert solution.solve([5], 1) == True


def test_matches_brute_force_for_small_arrays():
